import os
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Union

import boto3


def _to_epoch_ms(value: Union[datetime, int, float, str]) -> int:
    if isinstance(value, datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return int(value.timestamp() * 1000)
    if isinstance(value, (int, float)):
        return int(value)
    if isinstance(value, str):
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return int(dt.timestamp() * 1000)
    raise TypeError("Unsupported time value type")


def _quote_filter_value(value: Any) -> str:
    s = str(value).replace("\\", "\\\\").replace('"', '\\"')
    return f'"{s}"'


def _build_filter_pattern(field_filters: Optional[Dict[str, Any]]) -> Optional[str]:
    if not field_filters:
        return None

    parts = []
    for field, value in field_filters.items():
        if value is None:
            continue
        parts.append(f'{{ $.{field} = {_quote_filter_value(value)} }}')

    return " ".join(parts) if parts else None


def retrieve_recent_logs(
    log_group_name: str,
    start_time: Union[datetime, int, float, str],
    end_time: Union[datetime, int, float, str],
    field_filters: Optional[Dict[str, Any]] = None,
    log_stream_names: Optional[List[str]] = None,
    limit: int = 100,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    client = boto3.client("logs", region_name=region_name or os.getenv("AWS_REGION"))

    params: Dict[str, Any] = {
        "logGroupName": log_group_name,
        "startTime": _to_epoch_ms(start_time),
        "endTime": _to_epoch_ms(end_time),
        "limit": limit,
    }

    filter_pattern = _build_filter_pattern(field_filters)
    if filter_pattern:
        params["filterPattern"] = filter_pattern

    if log_stream_names:
        params["logStreamNames"] = log_stream_names

    results: List[Dict[str, Any]] = []
    paginator = client.get_paginator("filter_log_events")

    for page in paginator.paginate(**params):
        for event in page.get("events", []):
            results.append(
                {
                    "event_id": event.get("eventId"),
                    "timestamp": event.get("timestamp"),
                    "ingestion_time": event.get("ingestionTime"),
                    "log_stream_name": event.get("logStreamName"),
                    "message": event.get("message"),
                }
            )
            if len(results) >= limit:
                return results[:limit]

    return results


def ingest_log_events(
    log_group_name: str,
    log_stream_name: str,
    events: List[Dict[str, Any]],
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    client = boto3.client("logs", region_name=region_name or os.getenv("AWS_REGION"))

    normalized_events = []
    for event in events:
        if "message" not in event:
            raise ValueError("Each event must include a 'message'")
        timestamp = event.get("timestamp")
        if timestamp is None:
            timestamp = int(datetime.now(tz=timezone.utc).timestamp() * 1000)
        else:
            timestamp = _to_epoch_ms(timestamp)

        normalized_events.append(
            {
                "timestamp": timestamp,
                "message": str(event["message"]),
            }
        )

    normalized_events.sort(key=lambda e: e["timestamp"])

    try:
        client.create_log_stream(
            logGroupName=log_group_name,
            logStreamName=log_stream_name,
        )
    except client.exceptions.ResourceAlreadyExistsException:
        pass

    response = client.put_log_events(
        logGroupName=log_group_name,
        logStreamName=log_stream_name,
        logEvents=normalized_events,
    )

    return {
        "next_sequence_token": response.get("nextSequenceToken"),
        "rejected_log_events_info": response.get("rejectedLogEventsInfo"),
    }
